local function ruby_base64_decode(data)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup = {}
    for i = 1, #alphabet do
        lookup[alphabet:sub(i, i)] = i - 1
    end

    data = data:gsub("[^%w%+/=]", "")
    local output = {}
    local bitbuf, bitcount = 0, 0

    for i = 1, #data do
        local ch = data:sub(i, i)
        if ch == "=" then
            break
        end
        local v = lookup[ch]
        if v ~= nil then
            bitbuf = bitbuf * 64 + v
            bitcount = bitcount + 6
            if bitcount >= 8 then
                bitcount = bitcount - 8
                local byte = math.floor(bitbuf / (2 ^ bitcount)) % 256
                output[#output + 1] = string.char(byte)
                bitbuf = bitbuf % (2 ^ bitcount)
            end
        end
    end

    return table.concat(output)
end

local function ruby_get_logo_asset()
    if not writefile or not getcustomasset then
        return nil
    end

    local filename = "ruby_logo_embedded.png"
    local ok = pcall(function()
        writefile(filename, ruby_base64_decode(RUBY_LOGO_B64))
    end)

    if not ok then
        return nil
    end

    local success, asset = pcall(function()
        return getcustomasset(filename)
    end)

    if success then
        return asset
    end

    return nil
end

