function t2.value17(p5)
    local key = tostring(p5 or ""):gsub("%s+", "")
    if key == "" then
        return false, "INVALID"
    end

    local ok, accepted, status = pcall(function()
        if not RubySession then
            local initData, initError = rubyRequest("POST", "/api/v1/auth/init", {
                appId = RubyAppId,
                version = RubyVersion
            })

            if not initData or initData.success ~= true or not initData.session then
                return false, tostring((initData and initData.message) or initError or "API_ERROR")
            end

            RubySession = tostring(initData.session)
        end

        local data, requestError = rubyRequest("POST", "/api/v1/auth/validate", {
            appId = RubyAppId,
            key = key,
            version = RubyVersion,
            session = RubySession,
            hwid = v4()
        })

        if data and data.success == true and data.license and data.license.status == "active" then
            return true, "VALID"
        end

        local message = tostring((data and data.message) or requestError or "INVALID")

        -- Se a sessão estiver inválida, tenta um novo init uma única vez.
        if requestError == "HTTP_400" or message:lower():find("valid session", 1, true) then
            RubySession = nil
            local retryInit, retryError = rubyRequest("POST", "/api/v1/auth/init", {
                appId = RubyAppId,
                version = RubyVersion
            })
            if retryInit and retryInit.success == true and retryInit.session then
                RubySession = tostring(retryInit.session)
                local retryData, retryRequestError = rubyRequest("POST", "/api/v1/auth/validate", {
                    appId = RubyAppId,
                    key = key,
                    version = RubyVersion,
                    session = RubySession,
                    hwid = v4()
                })
                if retryData and retryData.success == true and retryData.license and retryData.license.status == "active" then
                    return true, "VALID"
                end
                return false, tostring((retryData and retryData.message) or retryRequestError or retryError or "INVALID")
            end
        end

        return false, message
    end)

    if not ok then
        return false, "API_ERROR"
    end

    return accepted == true, tostring(status or "INVALID")
end

