local v144
-- ============================================================
-- RUBY | SCORES
-- Funções de ScoreEffect e PlayerCard portadas da source 7m pago
-- ============================================================
local rubyScores = {
    scoreEnabled = false,
    playerCardEnabled = false,
    scoreEffect = "SupernovaScoreEffect",
    scoreConnections = {},
    playerCardConnections = {},
    playerCardBusy = false,
}

t2.value26.ScoresEnabled = false
t2.value26.ScoreEffect = rubyScores.scoreEffect
t2.value26.PlayerCard = "UltimateChampionPlayerCard"

local function rubyGetKnitServices()
    local ReplicatedStorage = t2.value5
    local Packages = ReplicatedStorage and ReplicatedStorage:FindFirstChild("Packages")
    local Index = Packages and Packages:FindFirstChild("_Index")
    local KnitFolder = Index and Index:FindFirstChild("sleitnick_knit@1.7.0")
    local Knit = KnitFolder and KnitFolder:FindFirstChild("knit")
    return Knit and Knit:FindFirstChild("Services")
end

local function rubyDisconnectList(list)
    for i, connection in pairs(list) do
        if connection then
            pcall(function()
                connection:Disconnect()
            end)
        end
        list[i] = nil
    end
end

local function rubyGetScoreEffects()
    local names = {}
    local seen = {}
    local ScoreEffect = t2.value5:FindFirstChild("Assets")
        and t2.value5.Assets:FindFirstChild("ScoreEffect")

    if ScoreEffect then
        for _, child in ipairs(ScoreEffect:GetChildren()) do
            if child:IsA("ModuleScript") then
                local name = child.Name
                if (name == "SupernovaScoreEffect"
                    or name == "MoonlightBeamScoreEffect"
                    or name == "VioletBeamScoreEffect"
                    or name == "Season10ProScoreEffect") and not seen[name] then
                    seen[name] = true
                    table.insert(names, name)
                end
            end
        end
    end

    -- Keep the known source options available even if the asset folder is not
    -- populated at the moment the UI is created.
    for _, name in ipairs({
        "SupernovaScoreEffect",
        "MoonlightBeamScoreEffect",
        "VioletBeamScoreEffect",
        "Season10ProScoreEffect",
    }) do
        if not seen[name] then
            table.insert(names, name)
            seen[name] = true
        end
    end

    return names
end

local function rubyApplyScoreEffect(position)
    if not rubyScores.scoreEnabled then
        return
    end

    local services = rubyGetKnitServices()
    local BallService = services and services:FindFirstChild("BallService")
    local RE = BallService and BallService:FindFirstChild("RE")
    local HitGround = RE and RE:FindFirstChild("HitGround")

    if not HitGround then
        return
    end

    local localName = t2.value23.Name
    local playerModel = workspace:FindFirstChild(localName)
        or workspace:FindFirstChild("uwuwuwiiwuw6")

    if not firesignal then
        return
    end

    pcall(function()
        firesignal(HitGround.OnClientEvent, {
            position,
            true,
            false,
            5,
            rubyScores.scoreEffect,
            playerModel,
            Vector3.new(-2.0885916001134e-06, 1, -4.710930170404e-06),
        })
    end)
end

local function rubyStartScoreEffect()
    if rubyScores.scoreConnections[1] then
        return
    end

    local function onIndicator(indicator)
        if not rubyScores.scoreEnabled then
            return
        end
        if not indicator or not indicator:IsA("BasePart") then
            return
        end
        if indicator.Name ~= "HitIndicator" then
            return
        end
        if indicator.Color == Color3.fromRGB(255, 0, 0) then
            return
        end
        if indicator.Color == Color3.fromRGB(0, 255, 0) then
            rubyApplyScoreEffect(indicator.Position)
        end
    end

    rubyScores.scoreConnections[1] = workspace.ChildAdded:Connect(function(child)
        onIndicator(child)
    end)

    rubyScores.scoreConnections[2] = workspace.DescendantAdded:Connect(function(descendant)
        onIndicator(descendant)
    end)

    local current = workspace:FindFirstChild("HitIndicator")
    if current then
        onIndicator(current)
    end
end

local function rubyStopScoreEffect()
    rubyDisconnectList(rubyScores.scoreConnections)
end

local function rubyStartPlayerCard()
    if rubyScores.playerCardConnections[1] then
        return
    end

    local services = rubyGetKnitServices()
