            pcall(function()
                descendant:Destroy()
            end)
            task.wait(0.1)
            rubyScores.playerCardBusy = false
            flashCard()
        end
    end)

    rubyScores.playerCardConnections[2] = t2.value23.PlayerGui.DescendantRemoving:Connect(function(descendant)
        if descendant.Name == "FlashPlayerCardFrame" then
            rubyScores.playerCardBusy = false
        end
    end)

    local Interface = t2.value23.PlayerGui:FindFirstChild("Interface")
    local Persistent = Interface and Interface:FindFirstChild("Persistent")
    local FlashFrame = Persistent and Persistent:FindFirstChild("FlashPlayerCardFrame")

    if FlashFrame and rubyScores.playerCardEnabled then
        pcall(function()
            FlashFrame:Destroy()
        end)
        task.wait(0.1)
        flashCard()
    end
end

